{"source": "def investigate(context, acquire):
    hist = acquire("history")

    def simulate(actions, put_mode, chan_mode, trig):
        committed = {}
        tx = {"main": None, "other": None}
        total = {"main": 0, "other": 0}
        last_changes = {"main": 0, "other": 0}

        def do_write(conn, key, value, is_put):
            nonlocal committed
            if tx[conn] is not None:
                view = tx[conn]
            else:
                view = committed
            existed = key in view
            direct = 0
            inserted = False
            if is_put:
                if existed:
                    if put_mode == "ignore":
                        direct = 0
                    elif put_mode == "replace":
                        view[key] = value
                        direct = 1
                        inserted = True
                    else:
                        view[key] = value
                        direct = 1
                        inserted = False
                else:
                    view[key] = value
                    direct = 1
                    inserted = True
            else:
                if existed:
                    view[key] = value
                    direct = 1
                else:
                    direct = 0
            trig_changes = 0
            if trig and inserted:
                trig_changes = 1
            last_changes[conn] = direct
            total[conn] += direct + trig_changes

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "put":
                do_write(conn, act["key"], act["value"], True)
            elif op == "update":
                do_write(conn, act["key"], act["value"], False)
            elif op == "delete":
                if tx[conn] is not None:
                    view = tx[conn]
                else:
                    view = committed
                if act["key"] in view:
                    del view[act["key"]]
                    last_changes[conn] = 1
                    total[conn] += 1
                else:
                    last_changes[conn] = 0
            elif op == "begin":
                if tx[conn] is None:
                    tx[conn] = dict(committed)
            elif op == "commit":
                if tx[conn] is not None:
                    committed = tx[conn]
                    tx[conn] = None
            elif op == "rollback":
                if tx[conn] is not None:
                    tx[conn] = None

        if chan_mode == "changes":
            channel = last_changes["main"]
        elif chan_mode == "total":
            channel = total["main"]
        else:
            channel = total["main"] + total["other"]
        return channel, len(committed), sum(committed.values())

    put_modes = ["ignore", "replace", "upsert"]
    chan_modes = ["changes", "total", "both"]
    trigs = [False, True]

    consistent = []
    for pm in put_modes:
        for cm in chan_modes:
            for tg in trigs:
                ok = True
                for rec in hist:
                    ch, cc, cs = simulate(rec["actions"], pm, cm, tg)
                    obs = rec["observed"]
                    if ch != obs["channel"] or cc != obs["committed_count"] or cs != obs["committed_sum"]:
                        ok = False
                        break
                if ok:
                    consistent.append((pm, cm, tg))

    if not consistent:
        return {"value": None, "unresolved": True}

    goal = context["goal"]
    vals = set()
    for pm, cm, tg in consistent:
        ch, cc, cs = simulate(context["actions"], pm, cm, tg)
        if goal == "channel":
            vals.add(ch)
        elif goal == "committed_count":
            vals.add(cc)
        else:
            vals.add(cs)
    if len(vals) == 1:
        return {"value": vals.pop(), "unresolved": False}
    return {"value": None, "unresolved": True}
", "scope": "Family of 18 SQLite sources: put mode (IGNORE/REPLACE/UPSERT), channel (changes/total/both), trigger (none/one AFTER INSERT).", "lesson": "Simulate each family member against all calibration receipts; answer only if all consistent members agree on the goal."}
